UPDATE public.daily_grammar_sentence_arrange SET prompt_text = 'Men bu ko‘lmakni aylanib o‘tolmay, oyog‘imni ho‘l qildim.' WHERE day_number = 60 AND sort_order = 4 AND answer_ru = 'Я не мог обойти эту лужу и промочил ноги.';
UPDATE public.daily_grammar_sentence_arrange SET prompt_text = 'Poyezd tunnelga kirdi va yo‘lovchilar yorug‘likni ko‘rdi.' WHERE day_number = 60 AND sort_order = 5 AND answer_ru = 'Поезд въехал в тоннель, и пассажиры увидели свет.';
UPDATE public.daily_grammar_sentence_arrange SET prompt_text = 'Bolalar maktabdan chiqib, stadionga yugurishdi.' WHERE day_number = 60 AND sort_order = 6 AND answer_ru = 'Дети вышли из школы и побежали на стадион.';
UPDATE public.daily_grammar_sentence_arrange SET prompt_text = 'U ishdan erta chiqib, uyga ketdi.' WHERE day_number = 60 AND sort_order = 7 AND answer_ru = 'Он ушёл с работы рано и поехал домой.';
UPDATE public.daily_grammar_sentence_arrange SET prompt_text = 'Biz Peterburgga poyezdda kelib, mehmonxonaga ketdik.' WHERE day_number = 60 AND sort_order = 8 AND answer_ru = 'Мы приехали в Петербург на поезде и пошли в гостиницу.';
UPDATE public.daily_grammar_sentence_arrange SET prompt_text = 'Mashina chuqurni aylanib o‘tdi va haydovchi xotirjam nafas oldi.' WHERE day_number = 60 AND sort_order = 9 AND answer_ru = 'Машина объехала яму, и водитель вздохнул с облегчением.';
